import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.DoRPXVp_.js";const h=JSON.parse('{"title":"ICE + WireGuard Shared Port","description":"","frontmatter":{"title":"ICE + WireGuard Shared Port"},"headers":[],"relativePath":"design/ice-wireguard-mux.md","filePath":"design/ice-wireguard-mux.md"}'),r={name:"design/ice-wireguard-mux.md"};function d(n,e,c,s,l,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="ice-wireguard-shared-port" tabindex="-1">ICE + WireGuard Shared Port <a class="header-anchor" href="#ice-wireguard-shared-port" aria-label="Permalink to &quot;ICE + WireGuard Shared Port&quot;">​</a></h1><blockquote><p>Source: <code>superpowers/specs/ice-wireguard-mux.md</code></p></blockquote><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Lattice uses a single UDP port <code>:51820</code> for both ICE signaling (STUN) and WireGuard data traffic. Two goroutines compete for packets on the same <code>net.UDPConn</code>:</p><table tabindex="0"><thead><tr><th>Packet type</th><th>Taken by <code>connWorker</code></th><th>Taken by <code>makeReceiveIPv4</code></th></tr></thead><tbody><tr><td>STUN</td><td>✅ correct → ICE</td><td>❌ WireGuard decrypt fails, dropped</td></tr><tr><td>WireGuard encrypted</td><td>❌ no ufrag match, dropped</td><td>✅ correct</td></tr></tbody></table><h2 id="solution-filteringudpmux" tabindex="-1">Solution: FilteringUDPMux <a class="header-anchor" href="#solution-filteringudpmux" aria-label="Permalink to &quot;Solution: FilteringUDPMux&quot;">​</a></h2><p><code>FilteringUDPMux</code> is a custom <code>UDPMux</code> that inspects each incoming packet before dispatching:</p><ol><li><strong>STUN packet</strong> (starts with <code>0x00</code> or <code>0x01</code>, magic cookie <code>0x2112A442</code>) → dispatch to ICE agent</li><li><strong>Non-STUN packet</strong> → dispatch to WireGuard <code>DefaultBind</code></li></ol><p>This eliminates the race condition. The ICE agent and WireGuard device each see only their own traffic.</p><h2 id="ice-agent-lifecycle" tabindex="-1">ICE Agent Lifecycle <a class="header-anchor" href="#ice-agent-lifecycle" aria-label="Permalink to &quot;ICE Agent Lifecycle&quot;">​</a></h2><p>After <code>agent.Dial()</code> / <code>Accept()</code> succeeds:</p><ul><li>ICE agent is closed — <code>connWorker</code> goroutine stops</li><li>WireGuard&#39;s <code>PersistentKeepalive</code> maintains the NAT mapping</li><li>STUN keepalive is not needed and is eliminated</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>internal/agent/transport/</span></span>
<span class="line"><span>└── filtering_mux.go   # FilteringUDPMux implementation</span></span></code></pre></div><p>Key function: <code>isSTUN(buf []byte) bool</code> — checks the STUN magic cookie at bytes 4-7.</p>`,15)])])}const m=t(r,[["render",d]]);export{h as __pageData,m as default};
